BEGIN READ ONLY; SET LOCAL statement_timeout='5s';
SELECT current_database(), current_user;
SELECT owner.rolname AS owner,p.prosecdef,p.proconfig,p.proacl::text,md5(p.prosrc) AS body_md5 FROM pg_proc p JOIN pg_roles owner ON owner.oid=p.proowner WHERE p.oid='academy.sync_service_activation(uuid,text,integer)'::regprocedure;
SELECT count(*) AS writer_role_collision FROM pg_roles WHERE rolname='academy_activation_writer';
SELECT count(*) AS policy_collision FROM pg_policy WHERE polrelid='academy.service_activation'::regclass AND polname='academy_service_activation_sync_writer';
SELECT relrowsecurity,relforcerowsecurity FROM pg_class WHERE oid='academy.service_activation'::regclass;
ROLLBACK;
